/**
 * Data Storage Utility
 * Handles flow responses and campaign data persistence
 * Designed to be easily migratable to MongoDB
 */

const fs = require('fs');
const path = require('path');

class DataStorage {
  constructor(storagePath = './kumva-data') {
    this.storagePath = storagePath;
    this.initializeStorage();
  }

  /**
   * Initialize storage directory structure
   */
  initializeStorage() {
    const dirs = [
      this.storagePath,
      path.join(this.storagePath, 'flows'),
      path.join(this.storagePath, 'responses'),
      path.join(this.storagePath, 'campaigns')
    ];

    dirs.forEach(dir => {
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
    });
  }

  /**
   * Create or update a flow record
   * @param {string} flowId - Unique flow identifier
   * @param {Object} flowData - Flow configuration and metadata
   */
  async saveFlow(flowId, flowData) {
    try {
      const flowPath = path.join(this.storagePath, 'flows', `${flowId}.json`);
      const data = {
        flowId,
        ...flowData,
        createdAt: flowData.createdAt || new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      fs.writeFileSync(flowPath, JSON.stringify(data, null, 2));
      return { success: true, flowId };
    } catch (error) {
      console.error('Error saving flow:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Get flow data
   * @param {string} flowId - Flow identifier
   */
  async getFlow(flowId) {
    try {
      const flowPath = path.join(this.storagePath, 'flows', `${flowId}.json`);
      
      if (!fs.existsSync(flowPath)) {
        return { success: false, error: 'Flow not found' };
      }

      const data = fs.readFileSync(flowPath, 'utf8');
      return { success: true, data: JSON.parse(data) };
    } catch (error) {
      console.error('Error retrieving flow:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Get all flows
   */
  async getAllFlows() {
    try {
      const flowsDir = path.join(this.storagePath, 'flows');
      const files = fs.readdirSync(flowsDir);
      const flows = [];

      files.forEach(file => {
        if (file.endsWith('.json')) {
          const data = fs.readFileSync(path.join(flowsDir, file), 'utf8');
          flows.push(JSON.parse(data));
        }
      });

      return { success: true, flows };
    } catch (error) {
      console.error('Error retrieving flows:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Create user session entry (campaign response)
   * @param {string} campaignId - Campaign identifier
   * @param {string} phoneNumber - User phone number
   * @param {Object} sessionData - Session metadata
   */
  async createUserSession(campaignId, phoneNumber, sessionData) {
    try {
      const sessionId = sessionData.sessionId || this.generateId();
      const responseDir = path.join(this.storagePath, 'responses', campaignId);

      if (!fs.existsSync(responseDir)) {
        fs.mkdirSync(responseDir, { recursive: true });
      }

      const sessionPath = path.join(responseDir, `${sessionId}.json`);
      const data = {
        sessionId,
        campaignId,
        phoneNumber,
        responses: [],
        metadata: {
          startedAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          status: 'active'
        },
        ...sessionData
      };

      fs.writeFileSync(sessionPath, JSON.stringify(data, null, 2));
      return { success: true, sessionId };
    } catch (error) {
      console.error('Error creating user session:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Add response to user session
   * @param {string} campaignId - Campaign identifier
   * @param {string} sessionId - Session identifier
   * @param {Object} response - Response data
   */
  async addResponse(campaignId, sessionId, response) {
    try {
      const sessionPath = path.join(
        this.storagePath,
        'responses',
        campaignId,
        `${sessionId}.json`
      );

      if (!fs.existsSync(sessionPath)) {
        return { success: false, error: 'Session not found' };
      }

      const sessionData = JSON.parse(fs.readFileSync(sessionPath, 'utf8'));
      
      sessionData.responses.push({
        ...response,
        timestamp: new Date().toISOString()
      });
      
      sessionData.metadata.lastUpdated = new Date().toISOString();

      fs.writeFileSync(sessionPath, JSON.stringify(sessionData, null, 2));
      return { success: true, data: sessionData };
    } catch (error) {
      console.error('Error adding response:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Get user session with all responses
   * @param {string} campaignId - Campaign identifier
   * @param {string} sessionId - Session identifier
   */
  async getSession(campaignId, sessionId) {
    try {
      const sessionPath = path.join(
        this.storagePath,
        'responses',
        campaignId,
        `${sessionId}.json`
      );

      if (!fs.existsSync(sessionPath)) {
        return { success: false, error: 'Session not found' };
      }

      const data = fs.readFileSync(sessionPath, 'utf8');
      return { success: true, data: JSON.parse(data) };
    } catch (error) {
      console.error('Error retrieving session:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Get all sessions for a campaign
   * @param {string} campaignId - Campaign identifier
   */
  async getCampaignSessions(campaignId) {
    try {
      const responseDir = path.join(this.storagePath, 'responses', campaignId);

      if (!fs.existsSync(responseDir)) {
        return { success: true, sessions: [] };
      }

      const files = fs.readdirSync(responseDir);
      const sessions = [];

      files.forEach(file => {
        if (file.endsWith('.json')) {
          const data = fs.readFileSync(path.join(responseDir, file), 'utf8');
          sessions.push(JSON.parse(data));
        }
      });

      return { success: true, sessions };
    } catch (error) {
      console.error('Error retrieving campaign sessions:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Save campaign metadata
   * @param {string} campaignId - Campaign identifier
   * @param {Object} campaignData - Campaign configuration
   */
  async saveCampaign(campaignId, campaignData) {
    try {
      const campaignPath = path.join(
        this.storagePath,
        'campaigns',
        `${campaignId}.json`
      );

      const data = {
        campaignId,
        ...campaignData,
        createdAt: campaignData.createdAt || new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      fs.writeFileSync(campaignPath, JSON.stringify(data, null, 2));
      return { success: true, campaignId };
    } catch (error) {
      console.error('Error saving campaign:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Get campaign metadata
   * @param {string} campaignId - Campaign identifier
   */
  async getCampaign(campaignId) {
    try {
      const campaignPath = path.join(
        this.storagePath,
        'campaigns',
        `${campaignId}.json`
      );

      if (!fs.existsSync(campaignPath)) {
        return { success: false, error: 'Campaign not found' };
      }

      const data = fs.readFileSync(campaignPath, 'utf8');
      return { success: true, data: JSON.parse(data) };
    } catch (error) {
      console.error('Error retrieving campaign:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Delete user session
   * @param {string} campaignId - Campaign identifier
   * @param {string} sessionId - Session identifier
   */
  async deleteSession(campaignId, sessionId) {
    try {
      const sessionPath = path.join(
        this.storagePath,
        'responses',
        campaignId,
        `${sessionId}.json`
      );

      if (fs.existsSync(sessionPath)) {
        fs.unlinkSync(sessionPath);
        return { success: true };
      }

      return { success: false, error: 'Session not found' };
    } catch (error) {
      console.error('Error deleting session:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Generate unique ID
   */
  generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }


  async deleteSessionResponses(sessionKey) {
    try {
      const path = `${this.storagePath}/responses/${sessionKey}`;
      const fs = require('fs');
      if (fs.existsSync(path)) {
        fs.rmSync(path, { recursive: true });
      }
      return { success: true };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async saveCampaignReport(campaignId, summary) {
    try {
      const fs = require('fs');
      const path = `${this.storagePath}/reports/${campaignId}`;
      if (!fs.existsSync(path)) fs.mkdirSync(path, { recursive: true });
      
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      fs.writeFileSync(`${path}/${timestamp}.json`, JSON.stringify(summary, null, 2));
      return { success: true };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async deleteSessionData(sessionKey) {
    try {
      const fs = require('fs');
      const path = `${this.storagePath}/sessions/${sessionKey}`;
      if (fs.existsSync(path)) {
        fs.rmSync(path, { recursive: true });
      }
      return { success: true };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }
}

module.exports = DataStorage;